from lib import Q
C='skin-science'
Q(C,'basic',"표피에서 가장 바깥에 있으며 죽은 각질 세포로 이루어진 층은?","각질층",[("기저층","표피의 가장 안쪽 층으로 새 세포를 만듭니다."),("유극층","표피 중간의 가장 두꺼운 층입니다."),("과립층","각질층 바로 아래 층입니다.")],"표피 가장 바깥 = 각질층","표피는 바깥부터 **각질층 – 투명층 – 과립층 – 유극층 – 기저층**입니다. 가장 바깥의 **각질층**은 죽은 각질 세포로 이루어져 피부를 보호합니다.",5,["표피"])
Q(C,'basic',"손바닥과 발바닥처럼 피부가 두꺼운 곳에만 있는 표피층은?","투명층",[("기저층","기저층은 온몸의 표피에 있습니다."),("유극층","유극층은 온몸의 표피에 있습니다."),("망상층","망상층은 진피의 층입니다.")],"손바닥·발바닥에만 = 투명층","**투명층**은 손바닥과 발바닥처럼 표피가 두꺼운 곳에만 있는 층으로, 엘라이딘이라는 물질이 있어 투명하게 보입니다.",4,["표피"])
Q(C,'intermediate',"피부색을 결정하는 멜라닌을 만드는 멜라닌 세포(멜라노사이트)가 주로 있는 층은?","기저층",[("유극층","면역을 맡는 랑게르한스 세포가 주로 있는 층입니다."),("각질층","죽은 세포로 된 가장 바깥층입니다."),("과립층","각질화가 시작되는 층입니다.")],"멜라닌 세포 = 기저층","**멜라닌 세포**는 표피의 가장 아래인 **기저층**에 있습니다. 기저층에서는 새 각질 세포도 만들어집니다.",5,["표피","멜라닌"])
Q(C,'intermediate',"표피의 유극층에 주로 있으며 외부에서 들어온 물질을 알아채는 면역 기능을 하는 세포는?","랑게르한스 세포",[("멜라닌 세포","피부색을 만드는 세포로 기저층에 있습니다."),("머켈 세포","촉감을 느끼는 데 관계하는 세포입니다."),("섬유아세포","진피에서 콜라겐과 엘라스틴을 만드는 세포입니다.")],"표피 면역 세포 = 랑게르한스 세포(유극층)","**랑게르한스 세포**는 주로 유극층에 있으며 피부로 들어온 이물질(항원)을 알아채 면역 반응을 돕습니다.",4,["표피","면역"])
Q(C,'intermediate',"진피에 있으며 피부가 늘어났다가 원래대로 돌아오게 하는 탄력섬유의 단백질은?","엘라스틴",[("콜라겐","진피의 대부분을 차지하는 교원섬유로, 탄력보다 피부를 단단하게 받쳐 주는 역할이 큽니다."),("케라틴","표피·손발톱·모발을 이루는 단백질입니다."),("멜라닌","피부색을 만드는 색소입니다.")],"탄력섬유 = 엘라스틴","진피에는 **교원섬유(콜라겐)**와 **탄력섬유(엘라스틴)**가 있습니다. 늘어났다가 되돌아오는 **탄력**은 엘라스틴이 맡습니다.",4,["진피"])
Q(C,'basic',"겨드랑이·유두 주변 등에 있으며 체취(몸 냄새)와 관계가 깊은 땀샘은?","아포크린선(대한선)",[("에크린선(소한선)","온몸에 퍼져 있고 체온 조절을 하는 작은 땀샘입니다."),("피지선","땀이 아니라 피지(기름)를 내보냅니다."),("갑상선","목에 있는 내분비샘으로 피부 땀샘이 아닙니다.")],"체취 땀샘 = 아포크린선","땀샘에는 온몸에 있는 **에크린선(소한선)**과 겨드랑이 등 특정 부위에 있는 **아포크린선(대한선)**이 있습니다. 아포크린선의 땀이 세균에 분해되면 체취가 납니다.",4,["피부 부속기관"])
Q(C,'intermediate',"피지선이 없는 곳은?","손바닥",[("얼굴","얼굴, 특히 이마와 코에는 피지선이 많습니다."),("두피","두피에는 피지선이 많습니다."),("가슴","가슴에도 피지선이 있습니다.")],"피지선 없는 곳 = 손바닥·발바닥","피지선은 손바닥과 발바닥을 뺀 거의 온몸에 있습니다. 그래서 **손바닥·발바닥**은 피지가 없어 건조해지기 쉽습니다.",4,["피부 부속기관"])
Q(C,'basic',"피지와 수분이 모두 부족해 당기고 잔주름이 생기기 쉬운 피부 유형은?","건성 피부",[("지성 피부","피지가 많아 번들거리는 피부입니다."),("중성(정상) 피부","피지와 수분이 균형을 이룬 피부입니다."),("복합성 피부","부위에 따라 지성과 건성이 섞인 피부입니다.")],"피지·수분 부족, 잔주름 = 건성 피부","**건성 피부**는 피지와 수분이 부족해 세안 뒤 당기고 각질과 잔주름이 생기기 쉽습니다. 보습을 충분히 해 줍니다.",3,["피부 유형"])
Q(C,'basic',"햇빛(자외선)을 받으면 피부에서 만들어지는 비타민은?","비타민 D",[("비타민 C","비타민 C는 음식으로 섭취해야 합니다."),("비타민 A","비타민 A는 음식으로 섭취합니다."),("비타민 B1","비타민 B1은 음식으로 섭취합니다.")],"자외선으로 피부에서 합성 = 비타민 D","**비타민 D**는 피부가 자외선을 받으면 만들어지며 칼슘 흡수를 도와 뼈를 튼튼하게 합니다.",4,["피부와 영양"])
Q(C,'intermediate',"멜라닌이 만들어지는 것을 억제하고 콜라겐 합성을 도와 미백 화장품에 많이 쓰이는 비타민은?","비타민 C",[("비타민 D","자외선으로 피부에서 만들어지며 뼈 건강에 관계합니다."),("비타민 K","혈액 응고에 관계합니다."),("비타민 B1","탄수화물 대사에 관계합니다.")],"미백·콜라겐 합성 = 비타민 C","**비타민 C**는 멜라닌 생성을 억제하고 콜라겐 합성을 도와 미백·피부 탄력에 쓰입니다.",4,["피부와 영양"])
Q(C,'intermediate',"주로 피부를 붉게 만들고(홍반) 일광화상을 일으키는 자외선은?","자외선 B(UVB)",[("자외선 A(UVA)","진피까지 들어가 색소 침착과 광노화에 주로 관계합니다."),("자외선 C(UVC)","대부분 오존층에서 흡수되어 땅에 거의 닿지 않습니다."),("적외선","열을 내는 광선으로 자외선이 아닙니다.")],"홍반·일광화상 = UVB","**자외선 B(UVB)**는 주로 표피에 작용해 피부를 붉게 하고 **일광화상**을 일으킵니다. 자외선 A는 더 깊이 들어가 색소 침착과 광노화에 관계합니다.",5,["피부와 광선"])
Q(C,'advanced',"나이가 들면서 생기는 자연(내인성) 노화의 변화로 옳지 않은 것은?","피지 분비가 늘어난다",[("표피와 진피가 얇아진다","옳은 설명입니다."),("콜라겐이 줄어든다","옳은 설명입니다."),("피부 재생 속도가 느려진다","옳은 설명입니다.")],"자연 노화 = 피지·콜라겐 감소, 피부 얇아짐","자연(내인성) 노화가 오면 피부가 얇아지고 콜라겐이 줄며 재생이 느려집니다. **피지 분비는 줄어** 피부가 건조해집니다.",4,["피부 노화"],lock=True)
Q(C,'intermediate',"사마귀의 원인으로 알맞은 것은?","바이러스",[("곰팡이","곰팡이는 무좀·조갑진균증의 원인입니다."),("기생충","사마귀와 관계없습니다."),("비타민 과다","사마귀와 관계없습니다.")],"사마귀 = 바이러스 감염","**사마귀**는 사람 유두종 바이러스(HPV)에 감염되어 생기며 다른 사람이나 다른 부위로 옮을 수 있습니다. 사마귀가 있는 부위는 시술하지 않습니다.",3,["피부 질환"])
Q(C,'intermediate',"체액성 면역에서 항체를 만들어 내는 세포는?","B림프구",[("T림프구","세포성 면역을 맡는 림프구입니다."),("적혈구","산소를 운반합니다."),("혈소판","혈액 응고를 돕습니다.")],"항체 생성 = B림프구","후천(특이성) 면역에는 항체로 싸우는 **체액성 면역(B림프구)**과 세포가 직접 싸우는 **세포성 면역(T림프구)**이 있습니다.",3,["면역"])

C='cosmetics'
Q(C,'advanced',"화장품이 갖추어야 할 4대 요건에 해당하지 않는 것은?","치료성",[("안전성","4대 요건의 하나입니다(피부에 해가 없을 것)."),("안정성","4대 요건의 하나입니다(변질되지 않을 것)."),("유효성","4대 요건의 하나입니다(목적한 효과가 있을 것).")],"화장품 4대 요건 = 안전성·안정성·사용성·유효성","화장품의 4대 요건은 **안전성·안정성·사용성·유효성**입니다. 질병을 치료하는 것은 의약품의 목적이므로 **치료성**은 요건이 아닙니다.",5,["화장품 기초"],lock=True)
Q(C,'intermediate',"물에 기름이 작은 방울로 퍼져 있는 형태로, 산뜻한 로션·크림에 많은 유화 형태는?","수중유형(O/W)",[("유중수형(W/O)","기름 속에 물이 퍼진 형태로 더 무겁고 진득합니다."),("가용화","유화가 아니라 소량의 기름을 투명하게 녹이는 기술입니다."),("분산","안료 가루를 고르게 퍼지게 하는 기술입니다.")],"물 속 기름 = O/W(산뜻)","유화에는 물 속에 기름이 퍼진 **수중유형(O/W, oil in water)**과 기름 속에 물이 퍼진 **유중수형(W/O)**이 있습니다. O/W는 산뜻하고, W/O는 유분감이 많습니다.",4,["화장품 제조"])
Q(C,'intermediate',"소량의 기름 성분을 계면활성제로 물에 투명하게 녹이는 기술로, 화장수나 향수를 만들 때 쓰는 것은?","가용화",[("유화","기름과 물을 우윳빛으로 섞는 기술입니다."),("분산","녹지 않는 가루를 고르게 퍼지게 하는 기술입니다."),("응고","굳히는 것으로 화장품 제조 기술과 다릅니다.")],"투명하게 녹임 = 가용화(화장수·향수)","**가용화**는 적은 양의 기름 성분을 계면활성제로 물에 **투명하게** 녹이는 기술로 화장수·향수에 쓰입니다. 우윳빛이 되면 유화입니다.",4,["화장품 제조"])
Q(C,'intermediate',"물이나 기름에 녹지 않는 안료 가루를 고르게 퍼지게 하는 기술로, 파운데이션·마스카라 등에 쓰이는 것은?","분산",[("가용화","적은 기름을 물에 투명하게 녹이는 기술입니다."),("유화","물과 기름을 섞는 기술입니다."),("증류","액체를 끓여 성분을 나누는 방법입니다.")],"안료 고르게 퍼뜨림 = 분산","**분산**은 녹지 않는 고체 가루(안료)를 액체 속에 고르게 퍼지게 하는 기술입니다. 색조 화장품과 네일 폴리시처럼 안료가 들어가는 제품에 쓰입니다.",3,["화장품 제조"])
Q(C,'basic',"공기 중의 수분을 끌어당겨 피부를 촉촉하게 해 주는 대표적인 보습제는?","글리세린",[("에탄올","휘발해 오히려 피부를 건조하게 할 수 있습니다."),("아세톤","폴리시를 녹이는 용제로 피부를 건조하게 합니다."),("파라벤","미생물이 자라는 것을 막는 방부제입니다.")],"대표 보습제 = 글리세린","**글리세린**은 수분을 끌어당기는 보습제로 화장품에 널리 쓰입니다.",4,["화장품 원료"])
Q(C,'basic',"화장품에 미생물이 자라 변질되는 것을 막기 위해 넣는 성분으로 알맞은 것은?","파라벤류 같은 방부제",[("글리세린 같은 보습제","보습제는 수분을 지키는 성분입니다."),("향료","향을 내는 성분입니다."),("색소","색을 내는 성분입니다.")],"변질 방지 = 방부제(파라벤 등)","화장품에는 미생물이 자라 변질되는 것을 막는 **방부제**가 들어가며, 파라벤류가 대표적입니다.",3,["화장품 원료"])
Q(C,'intermediate',"자외선 차단제에 표시된 SPF가 나타내는 것은?","자외선 B(UVB)를 막는 정도",[("자외선 A(UVA)를 막는 정도","UVA 차단 정도는 PA(+, ++ 등)로 표시합니다."),("피부 보습 정도","SPF는 보습과 관계없습니다."),("미백 효과의 정도","SPF는 미백 지수가 아닙니다.")],"SPF = UVB 차단, PA = UVA 차단","**SPF**는 주로 홍반·화상을 일으키는 **자외선 B**를 막는 정도를 숫자로 나타냅니다. 자외선 A 차단 정도는 **PA**로 표시합니다.",4,["자외선 차단제"])
Q(C,'intermediate',"네일 폴리시에서 마른 뒤 단단하고 윤기 있는 막(피막)을 만드는 주성분은?","니트로셀룰로오스",[("아세톤","폴리시를 녹이는 용제로, 리무버의 주성분입니다."),("글리세린","보습제입니다."),("라놀린","양털에서 얻는 보습·유연 성분입니다.")],"폴리시 피막 = 니트로셀룰로오스","네일 폴리시는 **니트로셀룰로오스**가 막을 만들고, 수지·가소제·용제·안료가 더해져 만들어집니다. 용제가 날아가면 단단한 막이 남습니다.",4,["네일 화장물 성분"])
Q(C,'advanced',"계면활성제 가운데 피부 자극이 가장 적어 기초 화장품에 많이 쓰이는 것은?","비이온성 계면활성제",[("양이온성 계면활성제","살균·유연 효과가 있으나 자극이 가장 큰 편입니다."),("음이온성 계면활성제","세정력이 좋아 비누·샴푸에 쓰이고 자극이 있는 편입니다."),("양쪽성 계면활성제","자극이 적은 편이지만 비이온성보다는 큽니다.")],"자극 순서: 양이온 > 음이온 > 양쪽성 > 비이온","계면활성제의 피부 자극은 보통 **양이온성 > 음이온성 > 양쪽성 > 비이온성** 순서입니다. 자극이 가장 적은 **비이온성**은 기초 화장품에 많이 쓰입니다.",4,["화장품 원료"])
Q(C,'basic',"화장품법에서 기능성 화장품의 기능에 해당하지 않는 것은?","손발톱 무좀 치료",[("피부 미백에 도움","기능성 화장품의 기능입니다."),("피부 주름 개선에 도움","기능성 화장품의 기능입니다."),("자외선으로부터 피부 보호","기능성 화장품의 기능입니다.")],"기능성 화장품 = 미백·주름·자외선 차단 등","기능성 화장품은 미백, 주름 개선, 자외선 차단 등에 **도움**을 주는 제품입니다. 무좀 같은 질병의 **치료**는 의약품의 영역입니다.",4,["기능성 화장품"],lock=True)

C='hand-foot-anatomy'
Q(C,'intermediate',"한쪽 손을 이루는 뼈의 개수는?","27개",[("26개","한쪽 발의 뼈 개수입니다."),("14개","한쪽 손의 손가락뼈 개수입니다."),("8개","손목뼈 개수입니다.")],"한 손 = 손목뼈 8 + 손허리뼈 5 + 손가락뼈 14 = 27","한쪽 손은 다음과 같이 이루어집니다.\n1. 손목뼈(수근골) 8개\n2. 손허리뼈(중수골) 5개\n3. 손가락뼈(수지골) 14개\n\n합계 8 + 5 + 14 = **27개**입니다.",4,["손의 뼈"])
Q(C,'basic',"손목을 이루는 손목뼈(수근골)의 개수는?","8개",[("7개","발목뼈(족근골)의 개수입니다."),("5개","손허리뼈의 개수입니다."),("14개","손가락뼈의 개수입니다.")],"손목뼈 = 8개","손목에는 작은 **손목뼈(수근골) 8개**가 두 줄로 놓여 있습니다.",4,["손의 뼈"])
Q(C,'basic',"엄지손가락을 이루는 손가락뼈(지골)의 개수는?","2개",[("3개","엄지를 뺀 나머지 손가락의 뼈 개수입니다."),("1개","엄지는 2마디입니다."),("4개","손가락뼈는 4개인 손가락이 없습니다.")],"엄지 = 2마디, 나머지 손가락 = 3마디","엄지손가락은 첫마디뼈·끝마디뼈 **2개**, 나머지 네 손가락은 첫마디·중간마디·끝마디 3개씩입니다. 그래서 손가락뼈는 2 + 3×4 = 14개입니다.",3,["손의 뼈"])
Q(C,'intermediate',"발목을 이루는 발목뼈(족근골)의 개수는?","7개",[("8개","손목뼈의 개수입니다."),("5개","발허리뼈의 개수입니다."),("14개","발가락뼈의 개수입니다.")],"발목뼈 = 7개","발목뼈(족근골)는 **7개**입니다. 발꿈치뼈(종골)와 목말뼈(거골)가 대표적입니다.",3,["발의 뼈"])
Q(C,'advanced',"한쪽 발을 이루는 뼈의 개수는?","26개",[("27개","한쪽 손의 뼈 개수입니다."),("28개","발목뼈를 8개로 잘못 셌을 때의 수입니다."),("19개","발허리뼈와 발가락뼈만 더한 수입니다.")],"한 발 = 발목뼈 7 + 발허리뼈 5 + 발가락뼈 14 = 26","한쪽 발은 다음과 같이 이루어집니다.\n1. 발목뼈(족근골) 7개\n2. 발허리뼈(중족골) 5개\n3. 발가락뼈(족지골) 14개\n\n합계 7 + 5 + 14 = **26개**입니다.",3,["발의 뼈"])
Q(C,'intermediate',"손가락을 벌어지게 하는 근육은?","외전근(벌림근)",[("내전근(모음근)","손가락을 모으는 근육입니다."),("굴근(굽힘근)","손가락을 구부리는 근육입니다."),("신근(폄근)","손가락을 펴는 근육입니다.")],"벌림 = 외전근, 모음 = 내전근","손가락을 **벌리는** 근육은 **외전근(벌림근)**, 모으는 근육은 내전근(모음근)입니다. 구부리는 것은 굴근, 펴는 것은 신근입니다.",3,["손의 근육"])
Q(C,'advanced',"엄지손가락을 다른 손가락 끝과 마주 닿게 하여 물건을 집을 수 있게 하는 근육은?","대립근(맞섬근)",[("회내근(엎침근)","손바닥을 아래로 향하게 돌리는 근육입니다."),("외전근(벌림근)","손가락을 벌리는 근육입니다."),("신근(폄근)","손가락을 펴는 근육입니다.")],"엄지 맞대기 = 대립근(맞섬근)","**대립근(맞섬근)**은 엄지를 다른 손가락과 마주 보게 움직여 물건을 집게 합니다.",3,["손의 근육"])
Q(C,'advanced',"새끼손가락 쪽 손바닥과 손가락의 감각을 주로 맡는 신경은?","척골신경(자신경)",[("요골신경(노신경)","주로 손등의 엄지 쪽 감각과 손목을 펴는 근육을 맡습니다."),("정중신경","손바닥의 엄지·검지·중지 쪽 감각을 주로 맡습니다."),("좌골신경","다리에 있는 신경입니다.")],"새끼손가락 쪽 = 척골신경(자신경)","손의 신경은 **정중신경**(엄지~약지 절반의 손바닥 쪽), **척골신경(자신경)**(새끼손가락 쪽), **요골신경(노신경)**(손등 엄지 쪽)이 나누어 맡습니다.",3,["손의 신경"])
Q(C,'basic',"뼈 속에 있으며 적혈구 같은 혈액 세포를 만드는 곳은?","골수",[("골막","뼈 바깥을 싸는 막으로 뼈의 성장과 재생을 돕습니다."),("연골","관절 끝을 덮는 부드러운 뼈입니다."),("인대","뼈와 뼈를 이어 주는 조직입니다.")],"혈구 생성(조혈) = 골수","뼈 속 **골수**에서 적혈구·백혈구·혈소판이 만들어집니다. 이것을 뼈의 **조혈 기능**이라 합니다.",3,["뼈의 구조"])
Q(C,'advanced',"뼈의 기능에 해당하지 않는 것은?","호르몬을 만들어 혈액으로 내보내는 것이 주된 기능이다",[("몸을 지탱한다(지지)","뼈의 기능입니다."),("뇌·심장 같은 장기를 보호한다(보호)","뼈의 기능입니다."),("칼슘 같은 무기질을 저장한다(저장)","뼈의 기능입니다.")],"뼈의 기능 = 지지·보호·운동·조혈·저장","뼈의 기능은 **지지·보호·운동·조혈·저장**입니다. 호르몬을 만들어 내보내는 것은 내분비샘의 주된 기능입니다.",3,["뼈의 기능"],lock=True)
